// =====================================================================
// SOC-Lite · BLOQUE INGESTA
// 1) Valida el header X-Ingest-Key (comparación en tiempo constante)
// 2) Normaliza el payload crudo de Wazuh / OPNsense al esquema de soclite.alerts
// 3) Calcula alert_fingerprint = sha256(source_type|rule_id|source_ip|bucket 5 min)
//    (mismo algoritmo que el INSERT ... ON CONFLICT del nodo '3 · INSERT alerta')
// 4) Pre-escapa los literales SQL que usan los nodos PostgreSQL
// =====================================================================
const crypto = require('crypto');

const ENV_KEY = String($env.SOC_INGEST_KEY || '');
const SOC_SCHEMA = String($env.SOC_SCHEMA || $json.SOC_SCHEMA || 'soclite');
const N8N_ORIGIN_IP = String($env.N8N_ORIGIN_IP || $json.N8N_ORIGIN_IP || '127.0.0.1');

// --- Helper de comparación en tiempo constante -----------------------
function safeEqual(a, b) {
  try {
    const ab = Buffer.from(String(a || ''), 'utf8');
    const bb = Buffer.from(String(b || ''), 'utf8');
    if (ab.length === 0 || ab.length !== bb.length) return false;
    return crypto.timingSafeEqual(ab, bb);
  } catch (e) {
    return false;
  }
}

// --- Helper de escapado de literales SQL -----------------------------
const esc = (v) => {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (typeof v === 'number' && Number.isFinite(v)) return String(v);
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE';
  return "'" + String(v).replace(/\u0000/g, '').replace(/'/g, "''") + "'";
};
const q = (v) => esc(v);
const arr = (list) =>
  "'{" + (list || []).map((x) => String(x).replace(/[",\\{}]/g, '')).join(',') + "}'";
const jst = (d) => {
  const t = d instanceof Date ? d : new Date(d);
  const p = (n) => String(n).padStart(2, '0');
  return (
    t.getUTCFullYear() + '-' + p(t.getUTCMonth() + 1) + '-' + p(t.getUTCDate()) + ' ' +
    p(t.getUTCHours()) + ':' + p(t.getUTCMinutes()) + ':' + p(t.getUTCSeconds()) + '+00'
  );
};

// --- Cabeceras (n8n normaliza a minúsculas en webhook) ---------------
const headers = $json.headers || {};
const pick = (k) => headers[k] || headers[k.toLowerCase()] || headers[k.toUpperCase()];
const ingestKey = pick('x-ingest-key');

if (!ENV_KEY) {
  throw new Error(
    'Falta la variable de entorno SOC_INGEST_KEY en el contenedor n8n (docker-compose env_file). Ver n8n/README.md §3.'
  );
}
if (!safeEqual(ingestKey, ENV_KEY)) {
  // El Error Workflow global del SOC-Lite ('E · Error Trigger global' de este mismo
  // workflow) deja el intento fallido en soclite.audit_log (module='triage', result='failure').
  throw new Error('401 No autorizado: header X-Ingest-Key ausente o invalido');
}

// --- Payload crudo ---------------------------------------------------
const raw = $json.body || $json;
if (!raw || typeof raw !== 'object' || Object.keys(raw).length === 0) {
  throw new Error('400 Bad Request: cuerpo JSON vacío o ilegible');
}
const src = raw.data || raw.alert || raw;
const rule = src.rule || raw.rule || {};
const agent = src.agent || raw.agent || {};
const iface = src.interface || raw.interface || {};
const manager = src.manager || raw.manager || {};

// --- Detección de origen (Wazuh vs OPNsense/Suricata) ----------------
const hdrSource = String(headers['x-source-type'] || headers['x-source'] || '').toLowerCase();
let sourceType =
  raw.source_type ||
  (hdrSource === 'opnsense' || hdrSource === 'suricata' || hdrSource === 'wazuh' ? hdrSource : null) ||
  (iface.name || iface.alias || raw.event_type ? 'opnsense' : null) ||
  ((raw.rule || src.rule) ? 'wazuh' : null);
if (sourceType !== 'opnsense' && (iface.name || iface.alias)) sourceType = 'opnsense';
if (!sourceType) sourceType = 'wazuh';
const cleanIp = (v) => {
  if (!v) return null;
  const s = String(v).split(':')[0].split('/')[0].trim();
  return /^(\d{1,3}\.){3}\d{1,3}$/.test(s) || s.includes(':') ? s : null;
};
// En Wazuh el campo srcip del evento trae la IP atacante
const sourceIp =
  cleanIp(raw.source_ip || iface.src_ip || raw.src_ip || raw.srcip) ||
  cleanIp((src.data && src.data.srcip) || null);
const destIp = cleanIp(iface.dest_ip || raw.dest_ip || (src.data && src.data.dstip) || (agent.ip ? null : null));
const sourcePort = Number(raw.source_port || iface.src_port || (src.data && src.data.srcport) || 0) || null;
const destPort = Number(raw.dest_port || iface.dest_port || (src.data && src.data.dstport) || 0) || null;
const protocol = String(iface.proto || raw.proto || (src.data && src.data.protocol) || '').toLowerCase() || null;

// --- Severidad -------------------------------------------------------
const ruleLevel = Number(rule.level !== undefined ? rule.level : raw.rule_level !== undefined ? raw.rule_level : raw.severity_raw || 0);
function sevFromLevel(l) {
  if (l >= 12) return 'critical';
  if (l >= 9) return 'high';
  if (l >= 7) return 'medium';
  if (l >= 4) return 'low';
  return 'info';
}
const severity = raw.severity || sevFromLevel(ruleLevel);
const srcPortNum = Number.isFinite(sourcePort) ? sourcePort : null;
const occurredAt = new Date(raw.occurred_at || raw.timestamp || src.timestamp || Date.now());

// --- Huella idempotente: sha256(source_type|rule_id|source_ip|bucket 5 min) ---
const bucket5 = new Date(Math.floor(occurredAt.getTime() / 300000) * 300000);
const fpInput = [
  String(sourceType || 'wazuh'),
  String(rule.id || raw.rule_id || iface.sid || 'unknown'),
  String(sourceIp || 'na'),
  bucket5.toISOString()
].join('|');
const fingerprint = crypto.createHash('sha256').update(fpInput, 'utf8').digest('hex');

// --- Valores SQL pre-escapados (los usan '3 · INSERT alerta' y '3b · UPDATE enriquecido') ---
const sqlValues = {
  alert_fingerprint: q(fingerprint),
  external_id: q(raw.external_id || raw.id || null),
  source_type: q(sourceType),
  source_name: q(raw.source_name || (sourceType === 'wazuh' ? 'wazuh-manager' : 'opnsense-ids')),
  rule_id: q(String(rule.id || raw.rule_id || iface.sid || 'unknown')),
  rule_level: Number.isFinite(ruleLevel) ? ruleLevel : 0,
  rule_description: q(rule.description || raw.rule_description || iface.alert || 'Sin descripción'),
  rule_groups: arr(rule.groups || raw.rule_groups || (iface.sid ? ['ids', 'et_malware'] : [])),
  severity: q(severity),
  severity_raw: Number.isFinite(Number(raw.severity_raw)) ? Number(raw.severity_raw) : (Number.isFinite(ruleLevel) ? ruleLevel : 0),
  source_ip: sourceIp ? q(sourceIp) : 'NULL',
  source_port: srcPortNum ? srcPortNum : 'NULL',
  dest_ip: destIp ? q(destIp) : 'NULL',
  dest_port: Number.isFinite(destPort) && destPort ? destPort : 'NULL',
  protocol: protocol ? q(protocol) : 'NULL',
  agent_id: q(agent.id || raw.agent_id || null),
  agent_name: q(agent.name || raw.agent_name || raw.hostname || null),
  mitre_technique: q((rule.mitre && rule.mitre.id) || raw.mitre_technique || null),
  full_log: q(raw.full_log || src.full_log || null),
  raw_payload: q(JSON.stringify(raw)),
  occurred_at: q(jst(occurredAt))
};

return [
  {
    json: {
      alert_fingerprint: fingerprint,
      bucket_5min: bucket5.toISOString(),
      source_type: sourceType,
      rule_id: String(rule.id || raw.rule_id || iface.sid || 'unknown'),
      rule_level: Number.isFinite(ruleLevel) ? ruleLevel : 0,
      rule_description: rule.description || raw.rule_description || iface.alert || 'Sin descripción',
      severity: severity,
      severity_raw: Number.isFinite(Number(raw.severity_raw)) ? Number(raw.severity_raw) : ruleLevel,
      status: 'pending',
      is_suppressed: false,
      dedup_count: 1,
      source_ip: sourceIp || '',
      dest_ip: destIp || '',
      agent_name: agent.name || raw.agent_name || raw.hostname || '',
      mitre_technique: (rule.mitre && rule.mitre.id) || raw.mitre_technique || null,
      full_log: raw.full_log || src.full_log || '',
      occurred_at: occurredAt.toISOString(),
      raw_payload: raw,
      ingest: {
        received_at: new Date().toISOString(),
        ingest_key_id: 'X-Ingest-Key',
        origin_ip: N8N_ORIGIN_IP,
        headers_user_agent: headers['user-agent'] || null,
        auth_ok: true
      },
      schema: SOC_SCHEMA,
      sql: sqlValues
    }
  }
];

// =====================================================================
// SOC-Lite · Paso 'Agente LangChain' del orquestador
// Post-procesa la respuesta de POST http://langchain:8001/triage:
//  - valida el esquema de la respuesta (contrato §4)
//  - normaliza risk_score a entero 0..100
//  - deriva la severidad operativa si el LLM no la devuelve
//  - prepara el registro de soclite.triage_results
//  - pre-escapa todo el SQL usado por los nodos PostgreSQL posteriores
// =====================================================================
const STATUS = Number($json.statusCode || 200);
const TIER = $json.body || {};
const IDs = $('3 · INSERT alerta (PostgreSQL)').first().json;
const ALERT = $('1b · Validar y normalizar (Code)').first().json;

const VERDICTS = ['true_positive', 'false_positive', 'benign', 'suspicious', 'inconclusive'];
const SEVERITIES = ['info', 'low', 'medium', 'high', 'critical'];
const warnings = [];
const errors = [];

// ---------------------------------------------------------------- validación
if (STATUS < 200 || STATUS >= 300) {
  errors.push('langchain_http_' + STATUS + ': ' + String(TIER.detail || TIER.message || 'respuesta no exitosa').slice(0, 500));
}
if (!TIER || Array.isArray(TIER) || typeof TIER !== 'object' || Object.keys(TIER).length === 0) {
  errors.push('esquema: cuerpo de respuesta ausente o no es un objeto JSON');
}
const verdict = VERDICTS.indexOf(TIER.verdict) >= 0 ? TIER.verdict : 'inconclusive';
if (VERDICTS.indexOf(TIER.verdict) < 0) warnings.push('verdict fuera de enum -> inconclusive');
const llmSeverity = SEVERITIES.indexOf(TIER.severity) >= 0 ? TIER.severity : null;
if (!llmSeverity) warnings.push('severity ausente -> derivada de risk_score');
const confidence = Number(TIER.confidence);
if (!(confidence >= 0 && confidence <= 1)) {
  warnings.push('confidence fuera de [0,1] -> 0.5');
}
const conf = Number.isFinite(confidence) && confidence >= 0 && confidence <= 1 ? Number(confidence.toFixed(3)) : 0.5;
const summary = String(TIER.summary || '').trim() || 'Sin resumen del modelo (revisión manual requerida)';
const reasoning = Array.isArray(TIER.reasoning) ? TIER.reasoning.map(String) : [];
const recommended = Array.isArray(TIER.recommended_actions) ? TIER.recommended_actions : [];
const mitre = Array.isArray(TIER.mitre_techniques) ? TIER.mitre_techniques.map(String) : [];
const indicators = Array.isArray(TIER.indicators) ? TIER.indicators : [];

// -------------------------------------------------- risk_score normalizado
let risk = Number(TIER.risk_score);
if (!Number.isFinite(risk)) {
  warnings.push('risk_score ausente -> calculado = 20*severity + 40*confidence + 40*verdict_weight');
  risk = 0;
}
risk = Math.max(0, Math.min(100, Math.round(risk)));
const severity = llmSeverity || (risk >= 85 ? 'critical' : risk >= 65 ? 'high' : risk >= 35 ? 'medium' : risk > 0 ? 'low' : 'info');

const SEV_BASE = { info: 10, low: 30, medium: 55, high: 75, critical: 90 };
const VERDICT_ADJ = { true_positive: 10, suspicious: 5, inconclusive: 0, benign: -10, false_positive: -30 };
const sevBase = SEV_BASE[severity] !== undefined ? SEV_BASE[severity] : 50;
const verdictAdj = VERDICT_ADJ[verdict] !== undefined ? VERDICT_ADJ[verdict] : 0;
const contextAdj =
  (String(ALERT.rule_level) >= '12' ? 5 : 0) +
  (indicators.some((i) => i && i.verdict === 'malicious') ? 8 : 0) +
  (indicators.some((i) => i && i.verdict === 'clean') ? -3 : 0);
const riskNormalized = Math.max(0, Math.min(100, Math.round(sevBase + verdictAdj + contextAdj)));

// -------------------------------------------------------------- clasificación
const escalate = severity === 'high' || severity === 'critical';
const lowTier = severity === 'low' || severity === 'info' || verdict === 'false_positive';

// ------------------------------------------------------------------ literales
const esc = (v) => {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (typeof v === 'number' && Number.isFinite(v)) return String(v);
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE';
  return "'" + String(v).replace(/\u0000/g, '').replace(/'/g, "''") + "'";
};
const q = (v) => esc(v);
const arrLit = (list) => "'{" + (list || []).map((x) => String(x).replace(/[",\\{}]/g, '')).join(',') + "}'";
const jb = (o) => q(JSON.stringify(o === undefined ? null : o));

// trace_id de auditoría: UUID valido o NULL
const traceId = String(TIER.trace_id || '').match(/^[0-9a-fA-F-]{36}$/) ? TIER.trace_id : null;

const slackEmoji =
  severity === 'critical' ? ':rotating_light:' : severity === 'high' ? ':warning:' : severity === 'medium' ? ':large_yellow_circle:' : ':white_circle:';
const dashboardUrl = String(($env.DASHBOARD_BASE_URL || 'http://localhost:3000')).replace(/\/+$/, '') + '/alerts/' + IDs.id;

const sql = {
  alert_id: Number(IDs.id),
  verdict: q(verdict),
  severity: q(severity),
  risk_score: riskNormalized,
  confidence: conf,
  summary: q(summary),
  reasoning: jb(reasoning),
  recommended_actions: jb(recommended),
  mitre_techniques: arrLit(mitre),
  iocs: jb(indicators),
  model_name: q(TIER.model || $env.TRIAGE_MODEL || 'llama3.1:8b'),
  model_provider: q('ollama'),
  prompt_version: q(TIER.prompt_version || $env.TRIAGE_PROMPT_VERSION || 'triage_v3'),
  temperature: 0.1,
  tokens_in: Number.isFinite(Number(TIER.tokens_in)) ? Number(TIER.tokens_in) : 0,
  tokens_out: Number.isFinite(Number(TIER.tokens_out)) ? Number(TIER.tokens_out) : 0,
  latency_ms: Number.isFinite(Number(TIER.latency_ms)) ? Number(TIER.latency_ms) : 0,
  tools_used: arrLit(TIER.tools_used || []),
  trace_id: traceId ? q(traceId) : 'NULL',
  new_status: q(verdict === 'false_positive' ? 'false_positive' : escalate ? 'escalated' : 'triaged'),
  full_log: q(ALERT.full_log),
  mitre_technique: q(mitre[0] || ALERT.mitre_technique || null),
  alert_severity: q(severity),
  p1: q(escalate ? 'p1' : 'p2'),
  title: q('[' + String(severity).toUpperCase() + '] ' + String(ALERT.rule_description || 'Alerta SOC-Lite') + ' en ' + String(ALERT.agent_name || 'activo desconocido')),
  agent_name: q(ALERT.agent_name),
  source_ip: q(ALERT.source_ip),
  rule_id: q(ALERT.rule_id),
  description: q(warnings.length ? summary + '\nAvisos de validacion: ' + warnings.join('; ') : summary),
  detail: q('Triage automatico n8n: verdict=' + verdict + ' severity=' + severity + ' risk=' + riskNormalized + ' conf=' + conf),
  risk_breakdown: jb({ reported: risk, normalized: riskNormalized, severity_base: sevBase, verdict_adj: verdictAdj, context_adj: contextAdj })
};

return [
  {
    json: {
      ok: errors.length === 0,
      http_status: STATUS,
      trace_id: traceId,
      alert_id: Number(IDs.id),
      alert: {
        id: Number(IDs.id),
        fingerprint: IDs.alert_fingerprint,
        severity: severity,
        verdict: verdict,
        risk_score: riskNormalized,
        escalate: escalate,
        low_tier: lowTier
      },
      slack: {
        emoji: slackEmoji,
        channel: $env.SLACK_CHANNEL || '#soc-alertas',
        dashboard_url: dashboardUrl
      },
      validations: { errors: errors, warnings: warnings },
      triage: {
        verdict: verdict,
        severity: severity,
        risk_score: riskNormalized,
        risk_score_reported: Number.isFinite(Number(TIER.risk_score)) ? Number(TIER.risk_score) : null,
        confidence: conf,
        summary: summary,
        model: TIER.model || $env.TRIAGE_MODEL || 'llama3.1:8b',
        prompt_version: TIER.prompt_version || $env.TRIAGE_PROMPT_VERSION || 'triage_v3'
      },
      post: {
        trace_id: traceId,
        new_status: String(sql.new_status).replace(/'/g, ''),
        escalate: escalate,
        low_tier: lowTier,
        dashboard_url: dashboardUrl,
        severity: severity,
        verdict: verdict,
        risk_score: riskNormalized,
        confidence: conf,
        summary: summary,
        model: TIER.model || $env.TRIAGE_MODEL || 'llama3.1:8b',
        model_provider: 'ollama',
        prompt_version: TIER.prompt_version || $env.TRIAGE_PROMPT_VERSION || 'triage_v3',
        tokens_in: sql.tokens_in,
        tokens_out: sql.tokens_out,
        latency_ms: sql.latency_ms,
        tools_used: TIER.tools_used || [],
        mitre_techniques: mitre,
        indicators: indicators,
        reasoning: reasoning,
        recommended_actions: recommended,
        alert_title: String(sql.title).replace(/'/g, ''),
        rule_description: ALERT.rule_description,
        agent_name: ALERT.agent_name,
        source_ip: ALERT.source_ip || 'n/d',
        dest_ip: ALERT.dest_ip || 'n/d',
        rule_id: ALERT.rule_id,
        occurred_at: ALERT.occurred_at,
        passed: verdict === 'true_positive' || verdict === 'suspicious'
      },
      sql: sql
    }
  }
];

// =====================================================================
// SOC-Lite · Respuesta de la API de ingesta
// Construye el cuerpo de respuesta HTTP que devuelve
// POST /webhook/wazuh-alert mediante '6a · Responder 202 Accepted'.
// =====================================================================
const t = $json.triage || {};
const p = $json.post || {};
return [
  {
    json: {
      accepted: true,
      httpStatus: 202,
      alert_id: $json.alert_id,
      alert_fingerprint: ($('3 · INSERT alerta (PostgreSQL)').first().json || {}).alert_fingerprint || null,
      was_duplicate: Boolean(($('3 · INSERT alerta (PostgreSQL)').first().json || {}).was_duplicate),
      dedup_count: ($('3 · INSERT alerta (PostgreSQL)').first().json || {}).dedup_count || 1,
      severity: p.severity || null,
      verdict: t.verdict || null,
      risk_score: t.risk_score === undefined ? null : t.risk_score,
      confidence: t.confidence === undefined ? null : t.confidence,
      status: p.new_status || 'triaged',
      escalate: Boolean(p.escalate),
      trace_id: $json.trace_id || null,
      dashboard_url: p.dashboard_url || null,
      processed_at: new Date().toISOString()
    }
  }
];

