// =====================================================================
// SOC-Lite · VARIANTE TELEGRAM (COMENTADA)
// Para activarla: 1) importar el nodo 'Telegram' (n8n-nodes-base.telegram,
// typeVersion 1.2) en lugar de este Code node; 2) crear la credencial
// 'Telegram SOC-Lite Bot'; 3) usar el chat ID de soclite.integrations
// (code='telegram'). El mensaje debe respetar el mismo formato que Slack.
// ---------------------------------------------------------------------
/*
{
  "name": "8b · Telegram alerta alta/crítica (variante)",
  "type": "n8n-nodes-base.telegram",
  "typeVersion": 1.2,
  "parameters": {
    "resource": "message",
    "operation": "sendMessage",
    "chatId": "={{ $env.TELEGRAM_CHAT_ID }}",
    "text": "={{ '🚨 ALERTA ' + String($json.severity).toUpperCase() + ' · SOC-Lite\n' +
               'Activo: ' + ($json.agent_name || 'n/d') + ' | IP: ' + ($json.source_ip || 'n/d') + '\n' +
               'Riesgo: ' + $json.risk_score + '/100 | Veredicto: ' + $json.verdict + '\n' +
               $json.summary }}",
    "additionalFields": { "parse_mode": "Markdown" }
  }
}
*/
// Nodo NO-OP: deja pasar el ítem (variante Telegram desactivada en esta versión).
return [{ json: $json }];

// =====================================================================
// SOC-Lite · Apertura de ticket externo (osTicket / Redmine)
// Construye el cuerpo JSON del ticket a partir del triaje vigente.
// El nodo '9d · Normalizar ticket' extrae external_ticket_id de la respuesta.
// =====================================================================
const t = $json;
const env = $env;
const base = String(env.DASHBOARD_BASE_URL || 'http://localhost:3000').replace(/\/+$/, '');
const alertId = t.alert_id;
const sev = String(t.severity || 'medium').toUpperCase();
const subject = '[' + sev + '] SOC-Lite #' + alertId + ' · ' + (t.rule_description || 'Alerta de seguridad');
const body = [
  'Alerta SOC-Lite #' + alertId + ' (' + (t.alert_fingerprint || '').slice(0, 16) + '…)',
  '',
  'Severidad: ' + t.severity + '  |  Riesgo: ' + t.risk_score + '/100  |  Confianza: ' + t.confidence,
  'Veredicto del agente (' + (t.model_name || 'llama3.1:8b') + '): ' + t.verdict,
  'Activo: ' + (t.agent_name || 'n/d') + '   IP origen: ' + (t.source_ip || 'n/d'),
  'Regla: ' + (t.rule_id || 'n/d') + ' — ' + (t.rule_description || ''),
  'Ocurrencia: ' + (t.occurred_at || '') + '   Triaje: ' + (t.triaged_at || '') + '   SLA: ' + (t.sla_due_at || ''),
  '',
  'Resumen del LLM:',
  String(t.summary || ''),
  '',
  'Dashboard: ' + base + '/alerts/' + alertId
].join('\n');

return [
  {
    json: {
      alert_id: alertId,
      severity: t.severity,
      ticket_target: env.OSTICKET_API_URL ? 'osticket' : 'redmine',
      ticket: {
        alert: 'Security',
        source: 'SOC-Lite n8n',
        name: 'SOC-Lite Automation',
        email: 'soc-lite@org.local',
        subject: subject,
        message: body,
        priority: String(t.severity) === 'critical' ? 'Emergency' : 'High',
        topicId: 'seguridad',
        ip: t.source_ip || '',
        issue: { project_id: 1, subject: subject, description: body, priority_id: String(t.severity) === 'critical' ? 5 : 4 },
        soc_lite: { alert_id: alertId, fingerprint: t.alert_fingerprint, verdict: t.verdict, risk_score: t.risk_score }
      }
    }
  }
];

// =====================================================================
// SOC-Lite · Normaliza la respuesta del sistema de tickets
// Extrae external_ticket_id y external_ticket_url sea osTicket o Redmine.
// =====================================================================
const resp = $json.body || $json || {};
const prev = $('9a · Preparar ticket (Code)').first().json;
const base = String($env.OSTICKET_BASE_URL || 'https://soporte.org.local').replace(/\/+$/, '');

let ticketId = null;
let ticketUrl = null;
if (resp.id !== undefined && resp.id !== null && !resp.ticket_id) {
  // Redmine: {"issue":{"id":123,...}}
  ticketId = (resp.issue && resp.issue.id) || resp.id;
  ticketUrl = base + '/issues/' + ticketId;
} else if (resp.ticket_id) {
  ticketId = resp.ticket_id;
  ticketUrl = base + '/scp/tickets.php?id=' + ticketId;
} else if (resp.number) {
  ticketId = resp.number;
  ticketUrl = base + '/tickets/' + resp.number;
} else if (typeof resp === 'string' && resp.trim().length > 0) {
  ticketId = resp.trim().slice(0, 64);
}
if (ticketId === null) {
  ticketId = 'MANUAL-' + prev.alert_id;
  ticketUrl = null;
}

return [
  {
    json: Object.assign({}, prev, {
      external_ticket_id: String(ticketId),
      external_ticket_url: ticketUrl,
      ticket_http_status: Number($json.statusCode || 200),
      ticket_created: true
    })
  }
];
